EXPECTED = {
    "order_id": "int64",
    "amount": "float64",
    "status": "string",
}

def check_schema(df):
    actual = {c: str(t) for c, t in df.dtypes.items()}
    for col, dtype in EXPECTED.items():
        if col not in actual:
            raise SchemaDriftError(f"missing column: {col}")
        if actual[col] != dtype:
            raise SchemaDriftError(
                f"{col}: expected {dtype}, got {actual[col]}")
    return True
